def strlen(string: str) -> int:
    # Define the strlen function
    # Handle empty string case
    if not string:
        return 0

    # Handle whitespace case
    if string.isspace():
        return len(string.replace(" ", ""))

    # Handle ASCII and Unicode characters
    length = 0
    for char in string:
        length += 1

    return length

